$(function(){function t(n){return $('form[data-form-role="addtocart"][data-productid="'+n+'"]')}function n(n,i){var r=t(n),u=r.find('[name="id"]');u.val(i)}$('[data-input-role="combination_id"][data-for-product]').on("change",function(){var t=$(this).data("for-product"),i=$(this).val();n(t,i)});$('[data-input-role="combination_id"][data-for-product]').each(function(t,i){var r=$(i).data("for-product"),u=$(i).val();n(r,u)})});